import pathlib,json,hashlib,importlib.util
R=pathlib.Path.cwd();D=R/'evaluations/T-0818';I=D/'implementation';S=I/'stage487-v1';sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();hp=R/'evaluations/T-0781/implementation/stage_exact_two_settled_package_v2.py';sp=importlib.util.spec_from_file_location('h',hp);h=importlib.util.module_from_spec(sp);sp.loader.exec_module(h);c=h.conn(S/'stage.sqlite');state=h.state(c);result=json.load(open(S/'initial-result.json'));assert result['state']==state;assert sha(R/'genealogy2/data/research.sqlite')==json.load(open(D/'preparation/baseline-v1.json'))['main']['sha256'];pending=json.load(open(S/'actual-pending-full.json'));contexts=json.load(open(S/'actual-pending-contexts-initial.json'));assert len(pending)==len(contexts)==state['pending'];assert all(a==b['request']for a,b in zip(pending,contexts));paths=[p for p in S.rglob('*')if p.is_file()]+[I/'literal-manifest-v1.json',I/'stage-initial-UNRUN-v1.py',I/'seal-initial-stage-v1.py',D/'root-dual-literal-initial-clone-release-v1.json'];paths+=[p for p in D.glob('*literal*gate*.json')];pins=[{'path':str(p.relative_to(R)),'sha256':sha(p),'bytes':p.stat().st_size}for p in sorted(set(paths))];m={'task':'T-0818','state':state,'stage_sha256':sha(S/'stage.sqlite'),'actual_pending_count':len(pending),'context_sha256':sha(S/'actual-pending-contexts-initial.json'),'source_dispositions':None,'resolutions_applied':0,'native32_exact':True,'retains652_exact':True,'media_registration_file':'stage487-v1/actual-native-media-registration.json','all50_file':'stage487-v1/actual-all50.json','pins':pins,'main_unchanged':True,'canonicalApproval':False};p=I/'initial-stage-manifest-v1.json';assert not p.exists();p.write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'state':state,'manifest_sha256':sha(p),'stage_sha256':m['stage_sha256'],'context_sha256':m['context_sha256'],'pins':len(pins),'elapsed_seconds':result['elapsed_seconds']}))
